ata-end=&quot;1517&quot; data-start=&quot;1494&quot;&gt;bo mạch chủ bị hỏng&lt;/strong&gt;, khắc phục lỗi tủ điện chập cháy.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1622&quot; data-start=&quot;1552&quot;&gt;\r\n	&lt;p data-end=&quot;1622&quot; data-start=&quot;1554&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;line-height:1.5;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Khôi phục &lt;strong data-end=&quot;1587&quot; data-start=&quot;1564&quot;&gt;cấu hình điều khiển&lt;/strong&gt;, hiệu chỉnh các thông số vận hành.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h3 data-end=&quot;1663&quot; data-start=&quot;1624&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;line-height:1.5;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;&lt;strong data-end=&quot;1663&quot; data-start=&quot;1628&quot;&gt;2. Sửa chữa motor kéo – động cơ&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;1765&quot; data-start=&quot;1664&quot;&gt;\r\n	&lt;li data-end=&quot;1708&quot; data-start=&quot;1664&quot;&gt;\r\n	&lt;p data-end=&quot;1708&quot; data-start=&quot;1666&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;line-height:1.5;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Thay thế &lt;strong data-end=&quot;1707&quot; data-start=&quot;1675&quot;&gt;motor bị cháy, mòn chổi than&lt;/strong&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1765&quot; data-start=&quot;1709&quot;&gt;\r\n	&lt;p data-end=&quot;1765&quot; data-start=&quot;1711&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;line-heigh