&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;2426&quot; data-start=&quot;2318&quot;&gt;\r\n	&lt;li data-end=&quot;2377&quot; data-start=&quot;2318&quot;&gt;\r\n	&lt;p data-end=&quot;2377&quot; data-start=&quot;2320&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Ứng cứu khẩn cấp khi thang kẹt, mất điện, mất tín hiệu.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2426&quot; data-start=&quot;2378&quot;&gt;\r\n	&lt;p data-end=&quot;2426&quot; data-start=&quot;2380&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Đội ngũ chuyên nghiệp có mặt trong 30–60 phút.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h3 data-end=&quot;2453&quot; data-start=&quot;2428&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;3.6 Bảo trì định kỳ&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;2584&quot; data-start=&quot;2454&quot;&gt;\r\n	&lt;li data-end=&quot;2518&quot; data-start=&quot;2454&quot;&gt;\r\n	&lt;p data-end=&quot;2518&quot; data-start=&quot;2456&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Kiểm tra tổng thể điện – cơ, tra dầu, siết ốc, chạy thử tải.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2584&quot; data-start=&quot;2519&quot;&gt;\r\n	&lt;p data-end=&quot;2584&quot; data-start=&quot;2521&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;font-family:Times New Roman,Times,serif;&quot;&gt;Lập báo cáo chi tiết, tư vấn gi