INSERT INTO `table_product_list` VALUES (6,'thang-may-long-kinh','','','','','','','Thang máy lồng kính','z492326842181899138ebd3f05ae6ce89d84cd1635b61d-2700.jpg','{\"p\":\"z492326842181899138ebd3f05ae6ce89d84cd1635b61d-2700.jpg\",\"w\":960,\"h\":1280,\"m\":\"image\\/jpeg\"}',1,'','san-pham',1701209316,0),(7,'thang-may-thuc-pham','','','','','THANG MÁY TẢI THỰC PHẨM: GIẢI PHÁP AN TOÀN VÀ HIỆU QUẢ CHO NGÀNH CÔNG NGHIỆP THỰC PHẨM\r\n\r\nTrong ngành công nghiệp thực phẩm, việc vận chuyển hàng hóa một cách an toàn và hiệu quả là một yếu tố quan trọng để đảm bảo chất lượng và sự tươi ngon của sản phẩm. Thang máy tải thực phẩm đã trở thành một giải pháp không thể thiếu, đáp ứng nhu cầu vận chuyển hàng hóa trong môi trường thực phẩm một cách tiện lợi và đảm bảo vệ sinh.\r\n\r\n1. Đáp ứng các yêu cầu vận chuyển thực phẩm\r\n\r\nThang máy tải thực phẩm được thiết kế đặc biệt để đáp ứng các yêu cầu vận chuyển hàng hóa trong ngành công nghiệp thực phẩm. Dưới đây là một số điểm nổi bật của thang máy tải thực phẩm:\r\n\r\n- **Vệ sinh và an toàn**: Thang máy tải thực phẩm được làm từ các vật liệu chống gỉ và dễ dàng vệ sinh, nhằm đảm bảo sự an toàn và vệ sinh cho thực phẩm. Ngoài ra, chúng cũng được trang bị các hệ thống an toàn như cơ chế khóa an toàn và cảm biến để ngăn chặn va chạm và đảm bảo an toàn cho người vận hành.\r\n\r\n- **Kiểm soát nhiệt độ**: Thang máy tải thực phẩm thường được trang bị hệ thống kiểm soát nhiệt độ để duy trì điều kiện lý tưởng cho các loại thực phẩm nhạy cảm như thực phẩm tươi sống, đông lạnh hay đông lạnh sâu. Điều này giúp bảo quản và duy trì chất lượng của sản phẩm trong quá trình vận chuyển.','','Thang Máy Tải Thực Phẩm','6-6840.png','{\"p\":\"6-6840.png\",\"w\":583,\"h\":787,\"m\":\"image\\/png\"}',1,'noibat,hienthi','san-pham',1701209365,1701418737),(8,'thang-may-tai-khach','','','','','','','Thang máy tải khách','z492327006089946b58b5c0b5ec294995fa08b803b1d5f-5507.jpg','{\"p\":\"z492327006089946b58b5c0b5ec294995fa08b803b1d5f-5507.jpg\",\"w\":961,\"h\":1280,\"m\":\"image\\/jpeg\"}',1,'noibat,hienthi','san-pham',1701209396,1701209410),(9,'thang-may-tai-hang','','','','','','','Thang máy tải hàng ','','[]',3,'noibat,hienthi','san-pham',1732700816,0),(10,'thang-may-benh-vien','','','','','','','Thang máy bệnh viện ','','[]',4,'noibat,hienthi','san-pham',1732702185,0);
