INSERT INTO `table_seo` VALUES (944,0,'setting','update','setting','THANG MÁY NHÂN PHÁT','THANG MÁY NHÂN PHÁT','THANG MÁY NHÂN PHÁT, THANG MÁY ĐỒNG NAI, THANG MÁY BÌNH DƯƠNG, THANG MÁY VŨNG TÀU','','','','',''),(242,51,'news','man','chinh-sach','','','','','','','',''),(533,52,'news','man','chinh-sach','','','','','','','',''),(892,61,'news','man','dich-vu','','','','','','','{\r\n    &quot;@context&quot;: &quot;https://schema.org&quot;,\r\n    &quot;@type&quot;: &quot;NewsArticle&quot;,\r\n    &quot;mainEntityOfPage&quot;: {\r\n        &quot;@type&quot;: &quot;WebPage&quot;,\r\n        &quot;@id&quot;: &quot;http://thangmaynhanphat.com/dich-vu-bao-tri-sua-chua-thang-may-247&quot;\r\n    },\r\n    &quot;headline&quot;: &quot;Dịch vụ bảo trì sửa chữa thang máy 24/7&quot;,\r\n    &quot;image&quot;: &quot;http://thangmaynhanphat.com/upload/news/kiem-dinh-thang-may-1-1623578732975709275401-7208.jpg&quot;,\r\n    &quot;datePublished&quot;: &quot;2023-11-29T21:04:10+07:00&quot;,\r\n    &quot;dateModified&quot;: &quot;2024-12-10T19:15:51+07:00&quot;,\r\n    &quot;author&quot;: {\r\n        &quot;@type&quot;: &quot;Person&quot;,\r\n        &quot;name&quot;: &quot;THANG MÁY NHÂN PHÁT&quot;,\r\n        &quot;url&quot;: &quot;http://thangmaynhanphat.com/&quot;\r\n    },\r\n    &quot;publisher&quot;: {\r\n        &quot;@type&quot;: &quot;Organization&quot;,\r\n        &quot;name&quot;: &quot;THANG MÁY NHÂN PHÁT&quot;,\r\n        &quot;logo&quot;: {\r\n            &quot;@type&quot;: &quot;ImageObject&quot;,\r\n            &quot;url&quot;: &quot;http://thangmaynhanphat.com/upload/photo/logo-6-3313.png&quot;\r\n        }\r\n    }\r\n}',''),(240,49,'news','man','chinh-sach','','','','','','','',''),(239,48,'news','man','chinh-sach','','','','','','','',''),(238,47,'news','man','chinh-sach','','','','','','','',''),(512,6,'news','man_list','du-an','DỰ ÁN THANG MÁY BỆNH VIỆN','DỰ ÁN THANG MÁY BỆNH VIỆN','','','','','',''),(946,0,'static','update','gioi-thieu','Thang Máy Nhân Phát | Công Ty Cung Cấp, Lắp Đặt Và Bảo Trì Thang Máy','giới thiệu thang máy nhân phát, thang máy nhân phát, thang máy gia đình','Thang Máy Nhân Phát cung cấp giải pháp thang máy phù hợp cho nhà ở, biệt thự, tòa nhà và công trình cần lắp đặt, bảo trì, sửa chữa chuyên nghiệp.','','','','',''),(929,53,'news','man','tuyen-dung','Tuyển Dụng Chuyên Viên Thang Máy | Thang Máy Nhân Phát','tuyển dụng chuyên viên thang máy, tuyển kỹ thuật thang máy, việc làm thang máy tphcm','Thang Máy Nhân Phát tuyển dụng chuyên viên thang máy làm việc tại TP.HCM. Môi trường chuyên nghiệp, thu nhập cạnh tranh, cơ hội phát triển lâu dài.','','','','',''),(458,54,'news','man','tin-tuc','3 Lưu ý quan trọng trong sử dụng thang máy gia đình bạn cần biết','3 Lưu ý quan trọng trong sử dụng thang máy gia đình bạn cần biết','Biết cách khắc phục lỗi, vấn đề trong thang là vô cùng quan trọng và cần thiết, nếu gia đình bạn đã và đang lắp đặt thang máy sử dụng hãy tìm hiểu những kiến th','','','','{\r\n    &quot;@context&quot;: &quot;https://schema.org&quot;,\r\n    &quot;@type&quot;: &quot;NewsArticle&quot;,\r\n    &quot;mainEntityOfPage&quot;: {\r\n        &quot;@type&quot;: &quot;WebPage&quot;,\r\n        &quot;@id&quot;: &quot;http://thangmaynhanphat.com/3-luu-y-quan-trong-trong-su-dung-thang-may-gia-dinh-ban-can-biet&quot;\r\n    },\r\n    &quot;headline&quot;: &quot;3 Lưu ý quan trọng trong sử dụng thang máy gia đình bạn cần biết&quot;,\r\n    &quot;image&quot;: &quot;http://thangmaynhanphat.com/upload/news/thang-may-mini-gia-dinh-2-01-2433.jpg&quot;,\r\n    &quot;datePublished&quot;: &quot;2023-11-28T17:27:20+07:00&quot;,\r\n    &quot;dateModified&quot;: &quot;2024-12-10T19:55:39+07:00&quot;,\r\n    &quot;author&quot;: {\r\n        &quot;@type&quot;: &quot;Person&quot;,\r\n        &quot;name&quot;: &quot;THANG MÁY NHÂN PHÁT&quot;,\r\n        &quot;url&quot;: &quot;http://thangmaynhanphat.com/&quot;\r\n    },\r\n    &quot;publisher&quot;: {\r\n        &quot;@type&quot;: &quot;Organization&quot;,\r\n      