INSERT INTO `table_static` VALUES (5,'gioi-thieu-4822.jpg','{\"p\":\"gioi-thieu-4822.jpg\",\"w\":960,\"h\":1280,\"m\":\"image\\/jpeg\"}','cong-ty-tnhh-xay-dung-va-thang-may-nhan-phat','','','&lt;div style=&quot;max-width:100%; font-family:Arial, Helvetica, sans-serif; font-size:17px; line-height:1.7; color:#1f2937;&quot;&gt;\r\n&lt;div style=&quot;margin-bottom:22px;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0 0 14px 0; font-size:32px; line-height:1.35; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Giới thiệu về Thang Máy Nhân Phát&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:100px; height:4px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px; margin-bottom:18px;&quot;&gt; &lt;/div&gt;\r\n\r\n&lt;p style=&quot;margin:0 0 14px 0; text-align:justify;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;CÔNG TY TNHH XD &amp; THANG MÁY NHÂN PHÁT&lt;/strong&gt; là đơn vị hoạt động chuyên nghiệp trong lĩnh vực cung cấp, thi công, lắp đặt, bảo trì và sửa chữa thang máy. Với định hướng làm việc rõ ràng, chú trọng chất lượng và sự an tâm của khách hàng, Nhân Phát từng bước xây dựng uy tín thông qua những công trình thực tế, dịch vụ tận tâm và giải pháp phù hợp với từng nhu cầu sử dụng.&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin:0 0 14px 0; text-align:justify;&quot;&gt;Chúng tôi không chỉ cung cấp sản phẩm thang máy, mà còn đồng hành cùng khách hàng từ giai đoạn khảo sát, tư vấn, lên phương án lắp đặt đến bảo trì sau bàn giao. Mỗi công trình đều được nghiên cứu kỹ về mặt bằng, nhu cầu sử dụng, tính thẩm mỹ và chi phí đầu tư để mang lại hiệu quả sử dụng lâu dài.&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin:0; text-align:justify;&quot;&gt;Với đội ngũ kỹ thuật có kinh nghiệm thực tế, Nhân Phát hướng đến việc mang đến các giải pháp thang máy an toàn, vận hành ổn định, phù hợp cho nhà phố, biệt thự, văn phòng, khách sạn, nhà xưởng và nhiều loại công trình khác.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Thông tin doanh nghiệp&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:grid; grid-template-columns:repeat(auto-fit, minmax(260px, 1fr)); gap:16px; margin-bottom:10px;&quot;&gt;\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%); border:1px solid #dbe4ff;&quot;&gt;\r\n&lt;div style=&quot;font-size:15px; font-weight:700; text-transform:uppercase; color:#243d96; margin-bottom:8px;&quot;&gt;Tên doanh nghiệp&lt;/div&gt;\r\n\r\n&lt;div style=&quot;font-weight:700; color:#111827;&quot;&gt;CÔNG TY TNHH XD &amp; THANG MÁY NHÂN PHÁT&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%); border:1px solid #dbe4ff;&quot;&gt;\r\n&lt;div style=&quot;font-size:15px; font-weight:700; text-transform:uppercase; color:#243d96; margin-bottom:8px;&quot;&gt;Lĩnh vực hoạt động&lt;/div&gt;\r\n\r\n&lt;div&gt;Cung cấp, lắp đặt, bảo trì, sửa chữa và tư vấn giải pháp thang máy.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%); border:1px solid #dbe4ff;&quot;&gt;\r\n&lt;div style=&quot;font-size:15px; font-weight:700; text-transform:uppercase; color:#243d96; margin-bottom:8px;&quot;&gt;Khu vực phục vụ&lt;/div&gt;\r\n\r\n&lt;div&gt;TP.HCM và các khu vực lân cận theo nhu cầu thực tế của công trình.&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Sản phẩm và dịch vụ nổi bật&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:flex; flex-direction:column; gap:14px;&quot;&gt;\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Thang máy gia đình:&lt;/strong&gt; &lt;span&gt; Giải pháp thang máy nhỏ gọn, hiện đại, phù hợp với nhà phố, biệt thự và các công trình cần tối ưu diện tích nhưng vẫn đảm bảo sự tiện nghi trong di chuyển.&lt;/span&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Thang máy tải khách:&lt;/strong&gt; &lt;span&gt; Thiết kế đa dạng, chú trọng an toàn, độ bền và tính ổn định, phù hợp với tòa nhà, văn phòng, khách sạn, chung cư và công trình thương mại.&lt;/span&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Thang máy tải hàng:&lt;/strong&gt; &lt;span&gt; Dòng thang chuyên dùng để vận chuyển hàng hóa trong nhà máy, kho xưởng, trung tâm thương mại hoặc khu công nghiệp, có khả năng vận hành ổn định và đáp ứng tốt nhu cầu tải trọng lớn.&lt;/span&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Thang máy homelift:&lt;/strong&gt; &lt;span&gt; Dòng thang máy nhỏ gọn dành cho gia đình, tăng sự tiện lợi trong sinh hoạt, đồng thời góp phần nâng cao giá trị thẩm mỹ và hiện đại cho ngôi nhà.&lt;/span&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Bảo trì và sửa chữa:&lt;/strong&gt; &lt;span&gt; Hỗ trợ kiểm tra, bảo dưỡng định kỳ và xử lý sự cố nhanh chóng, giúp hệ thống vận hành an toàn, ổn định và bền bỉ hơn theo thời gian.&lt;/span&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border:1px solid #dbe4ff; border-radius:14px; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Tư vấn và thiết kế:&lt;/strong&gt; &lt;span&gt; Hỗ trợ khảo sát hiện trạng, đề xuất phương án phù hợp với từng công trình, tối ưu không gian lắp đặt, chi phí đầu tư và hiệu quả sử dụng lâu dài.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Năng lực và điểm mạnh của Nhân Phát&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:flex; flex-direction:column; gap:14px;&quot;&gt;\r\n&lt;div style=&quot;padding:16px 18px; border-left:4px solid #243d96; background:#f8faff; border-radius:12px;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Giải pháp phù hợp với từng công trình:&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Mỗi phương án đều được xem xét dựa trên hiện trạng mặt bằng, mục đích sử dụng, nhu cầu vận hành và ngân sách đầu tư để mang lại hiệu quả thực tế.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border-left:4px solid #243d96; background:#f8faff; border-radius:12px;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Tối ưu cho không gian hạn chế:&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Nhân Phát có thể tư vấn các phương án lắp đặt phù hợp với công trình diện tích nhỏ, cải tạo nhà có sẵn hoặc yêu cầu tối ưu hố pit theo hiện trạng thực tế.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border-left:4px solid #243d96; background:#f8faff; border-radius:12px;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Thi công bài bản, đồng hành lâu dài:&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Chúng tôi không chỉ tập trung vào khâu lắp đặt mà còn chú trọng chất lượng bàn giao, dịch vụ bảo trì, bảo hành và hỗ trợ kỹ thuật sau khi công trình đi vào sử dụng.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border-left:4px solid #243d96; background:#f8faff; border-radius:12px;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Tư vấn rõ ràng, dễ hiểu:&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Khách hàng được hỗ trợ từ bước lựa chọn giải pháp, định hình chi phí đầu tư đến phương án sử dụng phù hợp, giúp quá trình ra quyết định thuận tiện và an tâm hơn.&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Quy trình làm việc&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:grid; grid-template-columns:repeat(auto-fit, minmax(220px, 1fr)); gap:14px;&quot;&gt;\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(135deg, rgba(36,61,150,0.06) 0%, rgba(95,127,230,0.10) 100%); border:1px solid rgba(36,61,150,0.10);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:8px;&quot;&gt;01&lt;/div&gt;\r\n\r\n&lt;div style=&quot;font-weight:700; margin-bottom:6px;&quot;&gt;Tiếp nhận nhu cầu&lt;/div&gt;\r\n\r\n&lt;div&gt;Ghi nhận thông tin công trình, mục đích sử dụng và mong muốn của khách hàng.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(135deg, rgba(36,61,150,0.06) 0%, rgba(95,127,230,0.10) 100%); border:1px solid rgba(36,61,150,0.10);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:8px;&quot;&gt;02&lt;/div&gt;\r\n\r\n&lt;div style=&quot;font-weight:700; margin-bottom:6px;&quot;&gt;Khảo sát và tư vấn&lt;/div&gt;\r\n\r\n&lt;div&gt;Đánh giá hiện trạng thực tế để đề xuất giải pháp phù hợp về kỹ thuật, thẩm mỹ và chi phí.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(135deg, rgba(36,61,150,0.06) 0%, rgba(95,127,230,0.10) 100%); border:1px solid rgba(36,61,150,0.10);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:8px;&quot;&gt;03&lt;/div&gt;\r\n\r\n&lt;div style=&quot;font-weight:700; margin-bottom:6px;&quot;&gt;Thi công và lắp đặt&lt;/div&gt;\r\n\r\n&lt;div&gt;Triển khai theo đúng phương án đã thống nhất, chú trọng tiến độ, an toàn và chất lượng hoàn thiện.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:18px; border-radius:14px; background:linear-gradient(135deg, rgba(36,61,150,0.06) 0%, rgba(95,127,230,0.10) 100%); border:1px solid rgba(36,61,150,0.10);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:8px;&quot;&gt;04&lt;/div&gt;\r\n\r\n&lt;div style=&quot;font-weight:700; margin-bottom:6px;&quot;&gt;Bàn giao và hậu mãi&lt;/div&gt;\r\n\r\n&lt;div&gt;Hướng dẫn sử dụng, hỗ trợ bảo trì, bảo hành và đồng hành lâu dài cùng công trình.&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Tầm nhìn và sứ mệnh&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:20px; border-radius:16px; background:linear-gradient(135deg, rgba(36,61,150,0.06) 0%, rgba(95,127,230,0.10) 100%); border:1px solid rgba(36,61,150,0.10);&quot;&gt;\r\n&lt;p style=&quot;margin:0 0 12px 0; text-align:justify;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Tầm nhìn:&lt;/strong&gt; Trở thành đơn vị thang máy uy tín, được khách hàng tin tưởng khi tìm kiếm giải pháp lắp đặt, bảo trì và vận hành thang máy phù hợp cho từng công trình.&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin:0; text-align:justify;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Sứ mệnh:&lt;/strong&gt; Mang đến sản phẩm và dịch vụ thang máy an toàn, tiện nghi, bền bỉ, góp phần nâng cao giá trị sử dụng và giá trị thẩm mỹ cho không gian sống và công trình của khách hàng.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Dự án tiêu biểu&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:20px; border-radius:16px; background:#f8faff; border:1px solid #dbe4ff;&quot;&gt;\r\n&lt;p style=&quot;margin:0 0 12px 0; text-align:justify;&quot;&gt;Anh có thể bổ sung tại đây các công trình tiêu biểu đã thi công để tăng độ tin cậy và sức thuyết phục cho trang giới thiệu.&lt;/p&gt;\r\n\r\n&lt;div style=&quot;display:flex; flex-direction:column; gap:10px;&quot;&gt;\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:#ffffff; border:1px solid #e5edff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Dự án 1:&lt;/strong&gt; [Tên công trình] – [Khu vực] – [Loại thang máy]&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:#ffffff; border:1px solid #e5edff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Dự án 2:&lt;/strong&gt; [Tên công trình] – [Khu vực] – [Loại thang máy]&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:#ffffff; border:1px solid #e5edff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Dự án 3:&lt;/strong&gt; [Tên công trình] – [Khu vực] – [Loại thang máy]&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Hồ sơ pháp lý và hồ sơ năng lực&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:grid; grid-template-columns:repeat(auto-fit, minmax(260px, 1fr)); gap:18px;&quot;&gt;\r\n&lt;div style=&quot;padding:22px; border-radius:16px; border:1px solid #dbe4ff; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:10px;&quot;&gt;Giấy phép đăng ký kinh doanh&lt;/div&gt;\r\n\r\n&lt;p style=&quot;margin:0 0 16px 0; text-align:justify;&quot;&gt;Bổ sung file PDF giấy phép đăng ký kinh doanh tại đây để khách hàng, đối tác và chủ đầu tư dễ dàng kiểm tra thông tin doanh nghiệp.&lt;/p&gt;\r\n&lt;a href=&quot;https://drive.google.com/file/d/1AOlfScA7-e-MeqcPXQ4_KpW8_3rytYdp/view?usp=sharing&quot; style=&quot;display:inline-block; padding:12px 18px; border-radius:10px; background:linear-gradient(135deg,#243d96 0%, #3557c7 100%); color:#ffffff; text-decoration:none; font-weight:700;&quot; target=&quot;_blank&quot;&gt;Xem giấy phép kinh doanh PDF &lt;/a&gt;\r\n\r\n&lt;div style=&quot;margin-top:10px; font-size:14px; color:#6b7280;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:22px; border-radius:16px; border:1px solid #dbe4ff; background:linear-gradient(180deg,#f8fbff 0%, #f2f6ff 100%);&quot;&gt;\r\n&lt;div style=&quot;font-size:22px; font-weight:800; color:#243d96; margin-bottom:10px;&quot;&gt;Hồ sơ năng lực công ty&lt;/div&gt;\r\n\r\n&lt;p style=&quot;margin:0 0 16px 0; text-align:justify;&quot;&gt;Chèn link hồ sơ năng lực để khách hàng và đối tác dễ theo dõi thông tin doanh nghiệp, năng lực thi công, sản phẩm và dự án tiêu biểu.&lt;/p&gt;\r\n&lt;a href=&quot;https://drive.google.com/file/d/1IliYfpl2IkQvVW2NHZ-mR8sRdw52TYz-/view?usp=drive_link&quot; style=&quot;display:inline-block; padding:12px 18px; border-radius:10px; background:#ffffff; border:1px solid #243d96; color:#243d96; text-decoration:none; font-weight:700;&quot; target=&quot;_blank&quot;&gt;Xem hồ sơ năng lực &lt;/a&gt;\r\n\r\n&lt;div style=&quot;margin-top:10px; font-size:14px; color:#6b7280;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:30px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Câu hỏi thường gặp&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:flex; flex-direction:column; gap:12px;&quot;&gt;\r\n&lt;div style=&quot;padding:16px 18px; border-radius:14px; background:#f8faff; border:1px solid #dbe4ff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Nhà diện tích nhỏ có lắp được thang máy không?&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Có. Tùy theo hiện trạng công trình, Nhân Phát sẽ tư vấn giải pháp phù hợp để tối ưu diện tích và công năng sử dụng.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border-radius:14px; background:#f8faff; border:1px solid #dbe4ff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Có hỗ trợ khảo sát và tư vấn không?&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Có. Khách hàng sẽ được hỗ trợ tiếp nhận nhu cầu, khảo sát hiện trạng và tư vấn phương án phù hợp trước khi triển khai.&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:16px 18px; border-radius:14px; background:#f8faff; border:1px solid #dbe4ff;&quot;&gt;&lt;strong style=&quot;color:#243d96;&quot;&gt;Sau khi lắp đặt có bảo trì và sửa chữa không?&lt;/strong&gt;\r\n\r\n&lt;div style=&quot;margin-top:6px; text-align:justify;&quot;&gt;Có. Nhân Phát hỗ trợ bảo trì, bảo hành và xử lý sự cố để khách hàng an tâm hơn trong quá trình sử dụng.&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin-top:30px; padding:22px; border-radius:16px; background:linear-gradient(135deg,#243d96 0%, #3557c7 100%); color:#ffffff;&quot;&gt;\r\n&lt;p style=&quot;margin:0 0 12px 0; text-align:justify;&quot;&gt;Chọn &lt;strong&gt;Thang máy Nhân Phát&lt;/strong&gt; là lựa chọn giải pháp phù hợp, an toàn và bền vững cho công trình. Chúng tôi luôn sẵn sàng đồng hành từ khâu tư vấn, khảo sát đến lắp đặt và hậu mãi, giúp khách hàng yên tâm hơn trong quá trình đầu tư và sử dụng.&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin:0; text-align:justify;&quot;&gt;Nếu anh/chị đang cần tìm hiểu về thang máy gia đình, thang máy tải khách, thang máy tải hàng, phương án lắp đặt theo hiện trạng hoặc dịch vụ bảo trì sửa chữa, hãy liên hệ ngay để được hỗ trợ nhanh và đúng nhu cầu.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;margin:34px 0 18px 0;&quot;&gt;\r\n&lt;h2 style=&quot;margin:0; font-size:28px; line-height:1.4; font-weight:800; color:#243d96; text-transform:uppercase;&quot;&gt;Liên hệ để được tư vấn tốt hơn&lt;/h2&gt;\r\n\r\n&lt;div style=&quot;width:90px; height:3px; margin-top:10px; background:linear-gradient(90deg,#243d96 0%, #5f7fe6 100%); border-radius:999px;&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:24px; border-radius:18px; background:linear-gradient(180deg, rgba(36,61,150,0.92) 0%, rgba(49,75,160,0.88) 100%); color:#ffffff; box-shadow:0 8px 20px rgba(36,61,150,0.12); border:1px solid rgba(255,255,255,0.08);&quot;&gt;\r\n&lt;div style=&quot;font-size:24px; line-height:1.4; font-weight:800; margin-bottom:18px; text-transform:uppercase; color:#ffffff;&quot;&gt;CÔNG TY TNHH XD &amp; THANG MÁY NHÂN PHÁT&lt;/div&gt;\r\n\r\n&lt;div style=&quot;display:flex; flex-direction:column; gap:12px;&quot;&gt;\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.06);&quot;&gt;&lt;strong&gt;Địa chỉ:&lt;/strong&gt; Số 41 Trung Mỹ Tây 12, Phường Trung Mỹ Tây, TP.HCM&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.06);&quot;&gt;&lt;strong&gt;Điện thoại:&lt;/strong&gt; &lt;a href=&quot;tel:0933948386&quot; style=&quot;color:#ffffff; text-decoration:none;&quot;&gt;0933.94.8386&lt;/a&gt; &lt;span style=&quot;opacity:0.75;&quot;&gt; | &lt;/span&gt; &lt;strong&gt;Hotline:&lt;/strong&gt; &lt;a href=&quot;tel:0936455997&quot; style=&quot;color:#ffffff; text-decoration:none;&quot;&gt;0936.455.997&lt;/a&gt;&lt;/div&gt;\r\n\r\n&lt;div style=&quot;padding:12px 14px; border-radius:12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.06);&quo